ChatOperations_createChat.usage:
request := pachca.ChatCreateRequest{
	Chat: pachca.ChatCreateRequestChat{
		Name: "example",
		MemberIDs: []int32{int32(123)},
	},
}
response, err := client.Chats.CreateChat(ctx, request)

ChatOperations_updateChat.usage:
request := pachca.ChatUpdateRequest{
	Chat: pachca.ChatUpdateRequestChat{
		Name: pachca.Ptr("example"),
		Public: pachca.Ptr(true),
	},
}
response, err := client.Chats.UpdateChat(ctx, int32(123), request)
